def cards():
 result=[]
 for line in DATA.strip().splitlines():
  parts=line.split('|'); assert len(parts)==11,(len(parts),line)
  i,label,keywords,mode,roles,sources,en,ko,gate,boundary,edges=parts
  graph=[dict(zip(['from','relation','to'],edge.split('>'))) for edge in edges.split(';') if edge]
  nodes=sorted({n for e in graph for n in [e['from'],e['to']]})
  result.append(dict(id=i,label_ko=label,keyword_ids=['K'+x for x in keywords.split(',')],
   mode=mode,suggested_slots=sorted({ROLE_MAP.get(r,r) for r in roles.split(',') if r}),source_ids=sources.split(',') if sources else [],
   positive_en=en if mode!='context' else None,positive_ko=ko if mode!='context' else None,
   context_en=en if mode=='context' else None,context_ko=ko if mode=='context' else None,
   observable_gate=gate,confusion_boundary=boundary,research_owner_nodes=nodes,research_relations=graph,
   provenance='agent_authored_optional_realization' if mode!='context' else 'research_context_boundary',
   source_relation='Sources support specified vocabulary or context only, not every authored geometry or definition.',
   approval_status='research_only_not_native_qualified',runtime_importable=False,pixel_status='NOT_RUN',
   lexical_status='specific_source_scope_only_other_definitions_pending',
   activation='Explicit requester meaning, independent owners, open dimensions and complete effects review required; no automatic activation from genre or tags.',
   effects_to_review=['participant count and ownership','all pose/contact/gaze changes','introduced objects, garments, layers and counts','camera/setting/media changes'],
   medium_scope='photo_or_illustration_review_separately; C05/C06 are depicted-media options, not default physical scenes'))
 return result

